<?php

declare(strict_types=1);

namespace App\Calls\Records;

use App\Contracts\CallSender;
use App\Support\CallKey;

/**
 * The signed calls of Records, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class RecordCalls
{
    public function __construct(private CallSender $sender) {}

    public function addLink(
        string $source,
        string $target,
        CallKey $requestKey = new CallKey(),
    ): LinkChanged {
        return $this->sender->send(AddLinkCall::from([
            'source' => $source,
            'target' => $target,
            'requestKey' => $requestKey,
        ]));
    }

    public function removeLink(
        string $source,
        string $target,
        CallKey $requestKey = new CallKey(),
    ): LinkChanged {
        return $this->sender->send(RemoveLinkCall::from([
            'source' => $source,
            'target' => $target,
            'requestKey' => $requestKey,
        ]));
    }
}
